import{_ as s,l,o as e,c as i,v as r,p as n,x as t,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"证明助手与依值类型直觉","description":"","frontmatter":{"title":"证明助手与依值类型直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/proof-assistants.md","filePath":"cs/proof-assistants.md","lastUpdated":1789023840000}'),c={name:"cs/proof-assistants.md"};function T(m,a,f,u,_,E){const o=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="证明助手与依值类型直觉" tabindex="-1">证明助手与依值类型直觉 <a class="header-anchor" href="#证明助手与依值类型直觉" aria-label="Permalink to &quot;证明助手与依值类型直觉&quot;">​</a></h1><div class="epigraph"><p>Curry–Howard：证明即程序，命题即类型。依值类型让类型依赖值，等式可在类型里出现。助手检查推导；人仍要给不变式与策略。计算理论补层在此封口。</p><footer>—— 据 Martin-Löf；Howard；The Univalent Foundations Program, Homotopy Type Theory 整理</footer></div><p>上一课<a href="/cs/smt-solver">SMT</a> 自动但碎片化，失败时给模型不给可搬运的证明对象。缺口是<strong>交互证明助手</strong>：Coq、Lean、Isabelle。本课直觉：类型 = 命题，项 = 证明；依值类型为何能写「长度为 \\(n\\) 的向量」。不教安装，不重写 λ 课的 β。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>简单类型 λ 对应直觉主义命题：\\(\\to\\) 是函数。要证 \\(\\forall n,\\ldots\\) 需要依值：\\(\\Pi n:\\mathbb{N}.\\,P(n)\\)。等式类型 \\(a=b\\) 的证明是同一化或改写。助手核：类型检查可判定（或可检查），信任基小。策略（tactic）生成项，核再验。相对 SMT：这里证明是一等对象，可抽取程序；代价是人写。</p><p><a href="/cs/natural-deduction">自然演绎</a> 的引入消去正是类型构造子/消去子。Hoare 三元组可内嵌为类型，或另做验证条件再 SMT——两条路可混（why3）。</p><h3 id="不是「ai-写完证明」" tabindex="-1">不是「AI 写完证明」 <a class="header-anchor" href="#不是「ai-写完证明」" aria-label="Permalink to &quot;不是「AI 写完证明」&quot;">​</a></h3><p>自动策略、 hammers 会调用 SMT，但仍要类型正确。不可判定的一阶碎片不会因依值类型变可判定；人选择归纳与引理。</p><p><span class="marginnote">Howard 1969 笔记；Martin-Löf 类型论。Coq/Lean 实现 CIC 变体。HoTT 书是同伦视角，本课不进路径类型。Isabelle/HOL 是简单类型高阶逻辑，另一风格，点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用「偶数 + 偶数 = 偶数」的归纳形状对照自然演绎 \\(\\forall\\) 引入。指出：终止检查对应完全正确；允许非终止则逻辑崩溃（\\(Y\\) 无类型）。对照<a href="/cs/recursion-theorem">递归定理</a>：助手里一般禁止无类型自应用。</p>',11)),(e(),n(h,null,{default:t(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROP%5B%22%E5%91%BD%E9%A2%98%22%5D%20--%3E%20TY%5B%22%E7%B1%BB%E5%9E%8B%22%5D%0A%20%20PF%5B%22%E8%AF%81%E6%98%8E%22%5D%20--%3E%20TM%5B%22%E4%BE%9D%E5%80%BC%E9%A1%B9%22%5D%0A%20%20TM%20--%3E%20KER%5B%22%E6%A0%B8%E7%B1%BB%E5%9E%8B%E6%A3%80%E6%9F%A5%22%5D%0A%20%20SMT%5B%22SMT%22%5D%20-.-%3E%20TAC%5B%22%E7%AD%96%E7%95%A5%E5%8F%AF%E8%B0%83%E7%94%A8%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计算理论课程收束：自动机到 TM，可计算与复杂，信息与数论，最后逻辑把「证明」连回程序。主干系统栈在<a href="/cs/to-systems-boundary">边界</a> 已封；本补层不重开 OS。后课若有附录文献，不插入这条课序。</p><p>抽取：构造性证明可变成程序；经典排中律抽取需额外机制。</p><p>宇宙层级避免 Russell。归纳类型同时给出构造与消去（递归）。抽取到 OCaml/Haskell 把计算部分变成程序，证明部分擦掉。Isabelle/HOL 用简单类型 + 高阶逻辑，自动化强、依值弱。本补层封口：主干系统栈已在<a href="/cs/to-systems-boundary">边界</a> 结束，计算理论课序不重开 OS。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CIC 的全体宇宙规则，不引入立方类型论。不把形式化数学库当作业清单。补层「计算理论」到此结束：后课默认，证明助手是检查依值项的核，与 SMT 互补而非替代。</p><p>核检查依值项，策略可调用 SMT，证明仍是一等对象。Curry–Howard 把自然演绎接回程序。计算理论补层封口，不重开已在系统边界结束的主干栈。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Curry–Howard：命题–类型，证明–程序。</li><li>依值类型表达依赖值的规范；核小、策略大。</li><li>与 SMT 分工：可搬运证明 vs 自动判定碎片。</li><li>出处：Martin-Löf；Howard；Coq/Lean 与 HoTT 文献。</li></ul>',9))])}const b=s(c,[["render",T]]);export{B as __pageData,b as default};
